import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getServiceById } from '../services/api';

export default function ServiceDetailsPage() {
  const { id } = useParams();
  const [service, setService] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  const platformFeePercentage = 10; // 10%
  const taxPercentage = 5; // 5%

  useEffect(() => {
    const fetchService = async () => {
      try {
        const data = await getServiceById(id);
        setService(data);
      } catch (err) {
        console.error('Failed to fetch service details', err);
      } finally {
        setLoading(false);
      }
    };
    fetchService();
  }, [id]);

  if (loading) return <div style={{ padding: '20px' }}>Loading service details...</div>;
  if (!service) return <div style={{ padding: '20px' }}>Service not found.</div>;

  const serviceFee = service.price;
  const platformFee = (serviceFee * platformFeePercentage) / 100;
  const tax = (serviceFee * taxPercentage) / 100;
  const totalCost = serviceFee + platformFee + tax;

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', maxWidth: '800px', margin: '0 auto' }}>
      <button onClick={() => navigate(-1)} style={{ marginBottom: '20px', cursor: 'pointer' }}>
        &larr; Back
      </button>

      <h2>{service.title}</h2>
      <p style={{ display: 'inline-block', background: '#eee', padding: '5px 10px', borderRadius: '4px' }}>
        {service.category}
      </p>

      <div style={{ marginTop: '20px', lineHeight: '1.6' }}>
        <h3>Description</h3>
        <p>{service.description}</p>
      </div>

      <div style={{ marginTop: '40px', padding: '20px', background: '#f9f9f9', borderRadius: '8px', border: '1px solid #ddd' }}>
        <h3>Booking Summary</h3>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
          <span>Service Fee:</span>
          <span>৳{serviceFee.toFixed(2)}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
          <span>Platform Fee ({platformFeePercentage}%):</span>
          <span>৳{platformFee.toFixed(2)}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', borderBottom: '1px solid #ddd', paddingBottom: '10px' }}>
          <span>Tax ({taxPercentage}%):</span>
          <span>৳{tax.toFixed(2)}</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '10px', fontWeight: 'bold', fontSize: '1.2em' }}>
          <span>Total Cost:</span>
          <span>৳{totalCost.toFixed(2)}</span>
        </div>

        <button style={{ marginTop: '20px', width: '100%', padding: '15px', background: '#28a745', color: '#fff', border: 'none', borderRadius: '4px', fontSize: '1.1em', cursor: 'pointer' }}>
          Book Now
        </button>
      </div>
    </div>
  );
}
